  spear: { name: "Lancer", titles: ["Spearhand", "Lancer", "Dragoon", "Wavepiercer", "Crownlance", "Horizon Dragoon"], damage: [2,3,3,4,4,4], pierce: [10,10,12,12,15,15] },
